#!/usr/bin/env python3
"""Build SK_final.ly (the verified skeleton) and plan.json (performance plan) from piece.py.

usage: python3 build_sk.py            writes both files and prints the bar/section map
Section-relative positions in piece.py are converted to absolute "bar:beat" here, so inserting bars
in one section can never desynchronise the notes, the roles and the tempo/dynamics map.
"""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import fl  # noqa: E402
from piece import SECTIONS, GLOBAL  # noqa: E402


def bars(s):
    return [b.strip() for b in s.replace('\n', ' ').split('|') if b.strip()]


def offsets():
    off, a = {}, 1
    for s in SECTIONS:
        off[s['id']] = a
        a += s['bars']
    return off


def absolute(p, a):
    b, beat = p.split(':')
    return f"{int(b) + a - 1}:{beat}"


def build():
    off = offsets()
    sk = {v: [] for v in fl.VOICES}
    plan = {'voices': GLOBAL['voices'], 'measure': GLOBAL['measure'],
            'tempo': [], 'fermatas': [], 'breaths': [], 'dynamics': [], 'roles': [], 'keep': [], 'pedal': []}
    for s in SECTIONS:
        a = off[s['id']]
        for v in fl.VOICES:
            bb = bars(s[v])
            if len(bb) != s['bars']:
                raise SystemExit(f"{s['id']} {v}: {len(bb)} bars, expected {s['bars']}")
            sk[v] += bb
        for key in ('tempo', 'fermatas', 'breaths', 'dynamics', 'pedal'):
            for e in s.get(key, []):
                e = dict(e)
                e['at'] = absolute(e['at'], a)
                if 'until' in e:
                    e['until'] = absolute(e['until'], a)
                plan[key].append(e)
        for r in s.get('roles', []):
            d = {'voice': r[0], 'at': absolute(r[1], a), 'until': absolute(r[2], a), 'role': r[3]}
            if len(r) > 4 and r[4]:
                d['landing_from'] = absolute(r[4], a)
            plan['roles'].append(d)
        for k in s.get('keep', []):
            plan['keep'].append({'voice': k[0], 'at': absolute(k[1], a), 'until': absolute(k[2], a), 'what': k[3]})
    for k in ('humanize', 'role_boost', 'role_level'):
        plan[k] = GLOBAL[k]
    if not plan['keep']:
        del plan['keep']
    return sk, plan, off


if __name__ == '__main__':
    sk, plan, off = build()
    fl.write(os.path.join(HERE, 'SK_final.ly'), sk, 'FINAL SKELETON (generated by build_sk.py from piece.py; do not edit by hand)')
    json.dump(plan, open(os.path.join(HERE, 'plan.json'), 'w'), indent=1)
    open(os.path.join(HERE, 'plan.json'), 'a').write('\n')
    n = fl.nbars(sk)
    print(n, 'bars;', ', '.join(f"{s['id']} {off[s['id']]}-{off[s['id']] + s['bars'] - 1}" for s in SECTIONS))
